/* OutcomeOS client. No external JS, no simulated live market prices. */
'use strict';
const $=s=>document.querySelector(s);
const S={user:null,csrf:'',ws:null,workspaces:[],overview:null,detail:null,view:'dashboard',activity:[],alerts:[],marketData:null,marketSource:'demo',selected:null,authMode:'register',search:'',threshold:15,panta:false,pantaStatus:null,pantaVerified:null,marketSearch:'',marketCategories:['sports','crypto','politics','entertainment','finance','science','world','other']};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>x==null?'—':Number(x).toLocaleString('en-US');
const pct=x=>x==null?'—':(Number(x)*100).toFixed(0)+'%';
const usd=x=>'$'+Number(x||0).toLocaleString('en-US',{maximumFractionDigits:0});
const dt=x=>x?new Date(/^\d{4}-\d{2}-\d{2}$/.test(x)?x+'T12:00:00':x).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'Unscheduled';
const dateTime=x=>x?new Date(x).toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'';
const pill=(status)=>{const cl=status==='open'?'':status==='resolved'?'blue':status==='demo'?'demo':status==='archived'?'gray':'gray';return `<span class="pill ${cl}">${esc(status)}</span>`;};
const blank=(title,txt)=>`<div class="empty"><span class="glyph">◈</span><strong>${esc(title)}</strong>${esc(txt)}</div>`;
// Call only same-origin API paths. Failures are classified so an HTTP 401 is not
// confused with a browser/network error. Never print credentials or response bodies.
const api=async(path,method='GET',data=null)=>{
 if(!path.startsWith('/api/'))throw new Error('Invalid API path');
 const headers={};
 if(method!=='GET'){headers['Content-Type']='application/json';headers['X-CSRF-Token']=S.csrf;}
 const controller=new AbortController();
 const timeout=setTimeout(()=>controller.abort(),30000);
 let r;
 try{
  r=await fetch(path,{method,headers,credentials:'same-origin',cache:'no-store',signal:controller.signal,body:data==null?null:JSON.stringify(data)});
 }catch(error){
  if(error?.name==='AbortError')throw new Error('The server did not respond within 30 seconds. Please retry.');
  throw new Error('Cannot reach the OutcomeOS server. Check your connection and try again.');
 }finally{clearTimeout(timeout);}
 if(r.status===0)throw new Error('Browser blocked the server request. Open the Production URL and check browser privacy settings.');
 let output;
 try{output=await r.json()}catch{throw new Error(`Unexpected server response (HTTP ${r.status}). Please retry later.`);}
 if(!r.ok){
  const error=new Error(`${output?.error||'Server request failed'} (HTTP ${r.status})`);
  error.httpStatus=r.status;
  throw error;
 }
 return output;
};
// Retry safe reads only. Never re-send a creation/forecast POST after an uncertain failure.
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function readApi(path,attempts=3){
 for(let n=1;;n++){
  try{return await api(path)}catch(error){
   if(n>=attempts || (error.httpStatus && ![429,502,503,504].includes(error.httpStatus)))throw error;
   await pause(400*n);
  }
 }
}
function showConnectivityError(message){
 const root=$('#app');
 if(!root)return;
 root.innerHTML=`<div class="connectivity-wrap" role="alert"><div class="connectivity-card">${brand()}<h1>Temporarily unable to reach OutcomeOS</h1><p>${esc(message)}</p><p>Your sign-in status could not be verified. This may be a temporary hosting or database connection issue.</p><button class="btn btn-primary" data-act="auth-retry">Retry connection</button><p class="subnote">If retries fail, check the Vercel function logs for /api/auth/me and /api/workspaces.</p></div></div>`;
}

function toast(message,error=false){const node=$('#toast-root');if(!node)return;node.innerHTML=`<div class="toast ${error?'error':''}">${esc(message)}</div>`;setTimeout(()=>{node.innerHTML=''},4200)}
const loading=(message='Loading workspace…')=>{const root=$('#content');if(root)root.innerHTML=blank(message,'One moment please.')};
// Commit a complete auth snapshot atomically. If a later workspace API call
// fails, keep the previous UI state rather than leaving a half-signed-in view.
async function refreshAuth(){
 const a=await readApi('/api/auth/me');
 if(!a.user){S.user=null;S.csrf='';S.ws=null;S.workspaces=[];S.overview=null;S.panta=!!a.panta_configured;render();return a;}
 const w=await readApi('/api/workspaces');
 const workspaces=w.workspaces||[];
 const workspace=(S.ws&&workspaces.some(x=>x.id===S.ws))?S.ws:(workspaces[0]?.id||null);
 const overview=workspace?await readApi('/api/workspaces/'+workspace):null;
 S.user=a.user;S.csrf=a.csrf||'';S.panta=!!a.panta_configured;
 S.workspaces=workspaces;S.ws=workspace;S.overview=overview;
 render();return a;
}
function showAuthError(message){
 const field=$('#auth-error');
 if(field){field.textContent=message;field.hidden=false;}
 else toast(message,true);
}
async function loadOverview(){if(!S.ws)return;const o=await readApi('/api/workspaces/'+S.ws);if(!Array.isArray(o.decisions))throw new Error('Server returned an invalid decision list.');S.overview=o;return o;}
function brand(){return `<div class="brand"><span class="brand-icon">◈</span><span>outcome<b>OS</b></span></div>`}
function authPage(){return `<div class="auth-wrap"><aside class="auth-visual">${brand()}<div><div class="eyebrow">DON'T JUST PREDICT THE FUTURE.</div><h2>Make decisions<br>worth getting<br><span style="color:var(--lime)">right.</span></h2><p>Transform uncertainty into clarity. Link prediction markets, gather your team's convictions, track evidence, and learn from every outcome.</p><svg viewBox="0 0 560 220" class="hero-graph" aria-hidden="true"><defs><linearGradient id="a" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#78e6a6" stop-opacity=".24"/><stop offset="1" stop-color="#78e6a6" stop-opacity="0"/></linearGradient></defs><path d="M0 190L65 172 95 179 157 133 214 145 263 104 321 111 386 77 436 92 495 35 560 19V220H0Z" fill="url(#a)"/><path d="M0 190L65 172 95 179 157 133 214 145 263 104 321 111 386 77 436 92 495 35 560 19" fill="none" stroke="#aaf6c2" stroke-width="3"/><circle cx="495" cy="35" r="7" fill="#b6f7bc"/></svg></div><small style="color:#8db4a8">POWERED BY THE WISDOM OF MARKETS + PEOPLE</small></aside><main class="auth-panel"><form id="auth-form" class="auth-form"><div class="eyebrow">WELCOME TO OUTCOMEOS</div><h1>${S.authMode==='register'?'Build a clearer future.':'Welcome back.'}</h1><p style="margin-bottom:30px">${S.authMode==='register'?'Create your decision intelligence workspace.':'Sign in to your team’s decision workspace.'}</p>${S.authMode==='register'?`<div class="field"><label class="form-label" for="display_name">Your name</label><input class="input" id="display_name" name="display_name" required maxlength="60" autocomplete="name" placeholder="Alex Rivera"></div>`:''}<div class="field"><label class="form-label" for="email">Work email</label><input class="input" id="email" type="email" name="email" required autocomplete="email" placeholder="you@company.com"></div><div class="field"><label class="form-label" for="password">Password</label><input class="input" id="password" name="password" type="password" minlength="${S.authMode==='register'?10:1}" required autocomplete="${S.authMode==='register'?'new-password':'current-password'}" placeholder="At least 10 characters"></div><button class="btn btn-primary" style="width:100%;margin-top:11px;padding:14px" type="submit">${S.authMode==='register'?'Create my workspace →':'Sign in →'}</button><p class="auth-error" id="auth-error" role="alert" hidden></p><button class="auth-retry" type="button" data-act="auth-retry">Retry server connection</button><div class="auth-switch">${S.authMode==='register'?'Already have an account?':'New to OutcomeOS?'} <button type="button" data-act="auth-switch">${S.authMode==='register'?'Sign in':'Create account'}</button></div><p class="subnote" style="margin-top:32px">New cloud workspaces start empty. Local examples, if enabled, are clearly marked synthetic. No wallet or trades required.</p></form></main></div>`}
function sidebar(){const links=[['dashboard','◫','Overview'],['decisions','◎','Decision rooms'],['markets','◇','Market intelligence'],['alerts','⚑','Signal alerts'],['lab','◈','Scenario lab'],['team','♧','Team & activity']];return `<aside class="sidebar">${brand()}<button class="workspace-switch" data-act="change-workspace"><span><small>WORKSPACE</small><strong>${esc(S.overview?.workspace?.name||'Choose workspace')}</strong></span><span>⌄</span></button><div class="sidebar-label">WORKSPACE</div><nav class="nav">${links.map(([key,icon,label])=>`<button data-view="${key}" class="${S.view===key?'active':''}"><span class="miniicon">${icon}</span><span>${label}</span></button>`).join('')}</nav><div class="side-foot"><div class="side-user"><div class="user-initials">${esc((S.user?.display_name||'U').slice(0,1).toUpperCase())}</div><div><b>${esc(S.user?.display_name)}</b><small>${esc(S.user?.email)}</small></div></div><button data-act="logout">↪ Sign out</button></div></aside>`}
function chrome(){return `<div class="layout">${sidebar()}<main class="main"><header class="topbar"><div class="crumb">WORKSPACE &nbsp; / &nbsp; <b>${esc(({dashboard:'Overview',decisions:'Decisions',markets:'Market intelligence',alerts:'Signal alerts',lab:'Scenario lab',team:'Team & activity',detail:'Decision room'})[S.view]||'Overview')}</b></div><div class="top-actions"><span class="live-dot" aria-hidden="true"></span><span class="pill ${S.panta?'':'demo'}">${S.panta?'Panta key configured':'Panta key not configured'}</span><button class="btn btn-mini" data-act="new-decision">+ New decision</button></div></header><div class="content" id="content"></div></main></div>`}
function footer(){return `<div class="footnote">OutcomeOS · Decision intelligence, not trading advice. Panta quotes are market prices, not calibrated probabilities. <a target="_blank" rel="noopener" href="https://docs.panta.market/">Powered by Panta</a></div>`}
function head(kicker,title,subtitle,right=''){return `<div class="heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="toolbar">${right}</div></div>`}
function stat(title,value,desc){return `<div class="stat"><small>${esc(title)}</small><strong>${esc(value)}</strong><span>${esc(desc)}</span></div>`}
function simpleTable(rows){if(!rows.length)return blank('No decisions yet','Create a decision room to start tracking uncertainty.');return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Decision / Question</th><th>Status</th><th>Team estimate</th><th>Panta links</th><th>Review</th></tr></thead><tbody>${rows.map(d=>`<tr><td><button class="text-button" data-act="open-decision" data-id="${d.id}">${esc(d.title)}</button><small>${esc(d.question)}</small></td><td>${pill(d.status)}</td><td><b>${pct(d.team_probability)}</b>${d.team_probability!=null?`<div class="progress"><span style="width:${Math.round(d.team_probability*100)}%"></span></div>`:''}</td><td>${num(d.link_count)}</td><td><button class="btn btn-mini" data-act="open-decision" data-id="${d.id}">Open →</button></td></tr>`).join('')}</tbody></table></div>`}
function overviewView(){const data=S.overview||{metrics:{},decisions:[]};const m=data.metrics,rows=data.decisions.filter(d=>d.status==='open');return `${head('COMMAND CENTER','Decisions, with conviction.','Turn uncertain outcomes into accountable, trackable decisions.',`<button class="btn btn-primary" data-act="new-decision">+ Create decision room</button>`)}<div class="hero"><div><div class="eyebrow">THE FUTURE IS UNCERTAIN. YOUR PROCESS SHOULDN’T BE.</div><h2>Every decision deserves<br>better intelligence.</h2><p>Bring evidence, team forecasts, and Panta market signals into one auditable decision-making process.</p></div><div class="orbit"><div class="ring"></div><div class="pulse"></div></div></div><div class="stats">${stat('Open decisions',m.open||0,'Actively being evaluated')}${stat('Resolved outcomes',m.resolved||0,'Learn from the result')}${stat('Connected markets',m.markets||0,'Live or labeled demo')}${stat('Brier score',m.brier==null?'—':Number(m.brier).toFixed(3),m.brier==null?'Resolve a decision to begin':'Lower is better')}</div><div class="cols"><div class="section"><div class="section-title"><h2>Active decision rooms</h2><button class="btn btn-mini" data-view="decisions">View all →</button></div>${simpleTable(rows.slice(0,7))}</div><div><div class="section"><div class="section-title"><h2>How OutcomeOS works</h2></div><div class="activity"><div class="activity-row"><span class="activity-dot"></span><div><b>1. Define a measurable outcome</b><small>Use an unambiguous YES/NO resolution criterion.</small></div></div><div class="activity-row"><span class="activity-dot"></span><div><b>2. Forecast, challenge, document</b><small>Record team estimates and evidence over time.</small></div></div><div class="activity-row"><span class="activity-dot"></span><div><b>3. Link a matching Panta market</b><small>Watch market prices as an independent signal.</small></div></div><div class="activity-row"><span class="activity-dot"></span><div><b>4. Resolve & calibrate</b><small>Measure forecasting accuracy with a Brier score.</small></div></div></div></div><div class="section" style="margin-top:15px"><div class="section-title"><h2>Signal provenance</h2></div><p class="subnote">${S.panta?'A Panta API key is configured. Choose Live in the Market intelligence page to query Panta.':'No Panta API key is configured. Demo market rows are fictional and never passed off as live.'} Panta market prices do not necessarily equal outcome probabilities.</p><button class="btn btn-mini" data-view="markets">Explore markets ↗</button></div></div></div>${footer()}`}
function decisionsView(){let rows=S.overview?.decisions||[];if(S.search)rows=rows.filter(x=>(x.title+' '+x.question+' '+x.category).toLowerCase().includes(S.search.toLowerCase()));return `${head('FORECAST WORKSPACES','Decision rooms','Document hypotheses, involve your team, and resolve the outcomes you care about.',`<button class="btn btn-primary" data-act="new-decision">+ New decision</button>`)}<div class="filter-row"><input class="input" id="decision-search" value="${esc(S.search)}" placeholder="⌕ Search decision rooms…" aria-label="Search decision rooms"><span class="pill gray">${rows.length} rooms</span></div><div class="grid-cards">${rows.map(d=>`<div class="decision-card"><div class="meta">${pill(d.status)}<span class="small-muted">${esc(d.category)}</span></div><h3>${esc(d.title)}</h3><p>${esc(d.question)}</p><div class="card-bottom"><div><span class="small-muted">TEAM ESTIMATE</span><strong style="display:block">${pct(d.team_probability)}</strong></div><div style="text-align:right"><span class="small-muted">${d.link_count} market links · ${d.forecast_count} estimates</span><br><button class="btn btn-mini" style="margin-top:7px" data-act="open-decision" data-id="${d.id}">Open room →</button></div></div></div>`).join('')}</div>${rows.length?'':blank('No matching rooms','Try a different search or create a new room.')}${footer()}`}
function chart(values){if(!values?.length)return `<div class="subnote">Not enough data for a history chart.</div>`;let points=values.map((v,i)=>[i*100/Math.max(1,values.length-1),95-90*v]);let line=points.map(([x,y],i)=>(i?'L':'M')+x.toFixed(2)+' '+y.toFixed(2)).join(' ');return `<svg class="timeline-chart" viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="Historical chart"><line x1="0" y1="50" x2="100" y2="50" stroke="#3c4a58" stroke-dasharray="1 2" stroke-width=".5"/><path d="${line}" fill="none" stroke="#9ef2c0" stroke-width="1.4" vector-effect="non-scaling-stroke"/><circle cx="${points.at(-1)[0]}" cy="${points.at(-1)[1]}" r="1.8" fill="#c4fbd1"/></svg>`}
function marketLink(l){const h=l.history||[];const latest=l.latest;return `<div class="market-row"><div style="min-width:0;flex:1"><h4>${esc(l.market_title)}</h4><p>${esc(l.match_explanation)}</p><div class="meta" style="margin-top:7px">${pill(l.source)}<span class="small-muted">${esc(latest?.phase||'unavailable')} · ${esc(dateTime(latest?.created_at)||'No snapshot')}</span></div>${h.filter(x=>x.yes_price!=null).length>1?chart(h.filter(x=>x.yes_price!=null).map(x=>x.yes_price)):''}</div><div style="text-align:right;min-width:85px"><div class="market-price">${pct(latest?.yes_price)}</div><span class="small-muted">YES quote</span><div style="display:grid;gap:4px;margin-top:8px"><button class="btn btn-mini" data-act="refresh-link" data-id="${l.id}" ${l.source!=='live'?'disabled':''}>↻ Refresh</button><button class="btn btn-mini btn-ghost" data-act="remove-link" data-id="${l.id}">Unlink</button></div></div></div>`}
function detailView(){const d=S.detail;if(!d)return blank('Decision not loaded','Return to the decision room list.');const owner=S.overview.members.some(x=>x.id===S.user.id&&x.role==='owner');const vals=[...d.forecasts].reverse().map(x=>x.probability);const exposure=d.team_probability==null?null:d.impact_usd*(1-d.team_probability);return `<button class="btn btn-ghost btn-mini" data-view="decisions">← Back to decisions</button><div class="heading" style="margin-top:15px"><div><div class="eyebrow">DECISION ROOM / #${d.id}</div><h1>${esc(d.title)}</h1><div class="meta">${pill(d.status)}<span class="small-muted">${esc(d.category)} · created ${esc(dt(d.created_at))} · deadline ${esc(dt(d.deadline))}</span></div></div><div class="toolbar">${d.status==='open'?`<button class="btn" data-act="edit-decision">Edit</button>${owner?'<button class="btn btn-primary" data-act="resolve">Resolve outcome</button>':''}`:''}${owner?'<button class="btn" data-act="share-report">Share decision report ↗</button>':''}</div></div><div class="details-top"><div class="section"><div class="eyebrow">THE QUESTION</div><h2 class="detail-question">${esc(d.question)}</h2><p style="color:var(--muted);font-size:13px">${esc(d.description||'No additional context recorded yet.')}</p><div class="subsection"><div class="section-title"><h2>Forecast history</h2><span class="small-muted">${d.forecasts.length} submissions</span></div>${chart(vals)}<div class="subnote">Team estimate = average of each member's most recent forecast, not a Panta quote.</div></div><div class="section-title"><h2>Forecasts & reasoning</h2>${d.status==='open'?'<button class="btn btn-mini" data-act="new-forecast">+ Add forecast</button>':''}</div>${d.forecasts.length?d.forecasts.slice(0,12).map(f=>`<div class="entry"><strong>${esc(f.author)} · ${pct(f.probability)}</strong><small> &nbsp; ${esc(dateTime(f.created_at))}</small>${f.reason?`<p>${esc(f.reason)}</p>`:''}</div>`).join(''):blank('No estimates yet','Contribute the first forecast.')}</div><div><div class="section"><div class="eyebrow">TEAM CONVICTION</div><div class="big-confidence">${pct(d.team_probability)}</div><p class="subnote">Latest estimate per member</p><div class="progress" style="margin:19px 0"><span style="width:${Math.round((d.team_probability||0)*100)}%"></span></div>${d.status==='resolved'?`<p class="pill blue">Actual outcome: ${d.outcome?'YES':'NO'}</p>`:''}${d.status==='open'?'<button class="btn btn-primary" data-act="new-forecast" style="width:100%">Update my forecast →</button>':''}</div><div class="section" style="margin-top:15px"><div class="eyebrow">DOWNSIDE SCENARIO</div><div class="exposure"><small class="subnote">Illustrative downside exposure</small><strong>${exposure==null?'—':usd(exposure)}</strong><small class="subnote">Loss impact × (1 − team YES estimate). Simplified assumption, not a financial projection.</small></div><button class="btn btn-mini" style="margin-top:12px" data-view="lab">Open scenario lab →</button></div></div></div><div class="cols"><div class="section"><div class="section-title"><h2>Panta market signals</h2>${d.status==='open'?`<button class="btn btn-mini" data-act="link-market">+ Link market</button>`:''}</div><div class="callout info">Only link markets with closely matching outcome definitions and resolution dates. A Panta YES quote is a trading price — not a scientifically calibrated probability.</div>${d.links.length?d.links.map(marketLink).join(''):blank('No Panta market links','Find a matching market in Market intelligence, or attach a clearly labeled example.')}</div><div class="section"><div class="section-title"><h2>Evidence notebook</h2><button class="btn btn-mini" data-act="add-note">+ Evidence</button></div>${d.notes.length?d.notes.map(n=>`<div class="entry"><strong>${esc(n.author)}</strong> <small>${esc(dateTime(n.created_at))}</small><p class="exp">${esc(n.body)}</p>${n.source_url?`<a href="${esc(n.source_url)}" target="_blank" rel="noopener noreferrer">Open reference ↗</a>`:''}</div>`).join(''):blank('No evidence yet','Add research notes and supporting URLs.')}</div></div>${footer()}`}
function marketsView(){
 const all=S.marketData?.items||[];
 const markets=S.marketSearch?all.filter(m=>(m.title+' '+m.category+' '+m.description).toLowerCase().includes(S.marketSearch.toLowerCase())):all;
 const status=S.pantaStatus;
 const sync=status?.last_sync;
 const diagnostic=S.pantaVerified;
 const statusCard=`<div class="section" style="margin-bottom:17px"><div class="section-title"><h2>Panta connection diagnostics</h2><span class="pill ${S.panta?'':'demo'}">${S.panta?'API key configured':'API key required'}</span></div><div class="meta" style="margin-bottom:12px"><span class="small-muted">Mode: read-only · Credentials stored on server only</span>${sync?`<span class="small-muted">Last sync: ${esc(dateTime(sync.finished_at))} · ${num(sync.updated)} new · ${num(sync.unchanged)} unchanged · ${num(sync.failed)} failed</span>`:''}</div><div class="filter-row"><button class="btn btn-mini" data-act="panta-check" ${!S.panta?'disabled title="Configure PANTA_API_KEY in your local environment"':''}>Test Panta connection</button><a class="btn btn-mini" href="https://github.com/Kaito-HQ/panta-api-playground" rel="noopener noreferrer" target="_blank">API key setup ↗</a></div>${diagnostic?`<div class="callout info"><strong>${esc(diagnostic.connection==='verified'?'Live API connection verified':'Connection not checked')}</strong> · ${esc(diagnostic.checked_at||'')} · catalog listing returned ${num(diagnostic.catalog_items)} item(s). This verifies access, not sports market availability.</div>`:`<p class="subnote">No live connection has been verified in this browser session. Test with your own API key. This application never displays the key.</p>`}</div>`;
 return `${head('PANTA INTEGRATION','Market intelligence','Explore live market signals and connect them to auditable decisions.','<a class="btn" target="_blank" rel="noopener noreferrer" href="https://www.panta.market/">Panta website ↗</a>')}${statusCard}<div class="callout ${S.marketSource==='live'?'info':''}"><strong>${S.marketSource==='demo'?'DEMO ONLY — FICTIONAL MARKET EXAMPLES':'LIVE MODE — PANTA API'}</strong><br>${S.marketSource==='demo'?'These examples are fictional and not available to trade on Panta.':'Catalog entries may have no prices; open market details for the latest quote. An API key and network connection are required.'}</div><div class="section"><div class="section-title"><h2>Explore markets</h2><div class="segmented"><button data-act="market-mode" data-source="demo" class="${S.marketSource==='demo'?'active':''}">Demo catalog</button><button data-act="market-mode" data-source="live" class="${S.marketSource==='live'?'active':''}">Live Panta</button></div></div>${S.marketSource==='live'?`<div class="filter-row"><select id="market-category" class="select" style="max-width:170px"><option value="">All categories</option>${S.marketCategories.map(t=>`<option value="${t}" ${S.marketCategory===t?'selected':''}>${t}</option>`).join('')}</select><select class="select" id="market-phase" style="max-width:170px">${['','primary','secondary','resolved','cancelled'].map(t=>`<option value="${t}" ${S.marketPhase===t?'selected':''}>${t||'All phases'}</option>`).join('')}</select><button class="btn btn-mini" data-act="fetch-markets">↻ Fetch live markets</button></div>`:''}<div class="filter-row"><input id="market-query" class="input" style="max-width:390px" aria-label="Filter loaded markets" value="${esc(S.marketSearch)}" placeholder="Search loaded market titles or descriptions…"><span class="small-muted">Showing ${markets.length} of ${all.length} loaded markets</span></div>${!S.marketData?blank('No catalog loaded',S.marketSource==='demo'?'Select demo catalog to explore.':'Click Fetch live markets to query Panta.'):(markets.length?`<div class="grid-cards">${markets.map(m=>`<div class="decision-card"><div class="meta">${pill(S.marketSource)}<span class="small-muted">${esc(m.category)} · ${esc(m.phase)}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.description||'No description available.')}</p><div class="card-bottom"><div><span class="small-muted">YES QUOTE</span><strong style="display:block">${pct(m.yesPrice)}</strong></div><div style="text-align:right"><button class="btn btn-mini" data-act="market-detail" data-id="${esc(m.marketId)}">View quotes</button><button class="btn btn-mini" style="margin-top:5px" data-act="link-selected" data-id="${esc(m.marketId)}">Link →</button></div></div></div>`).join('')}</div>`:blank('No matching markets','Change the text filter, category or phase.'))}${S.marketSource==='live'&&S.marketData?.nextCursor?'<div style="margin-top:20px"><button class="btn" data-act="more-markets">Load more →</button></div>':''}</div>${footer()}`;
}
function alertsView(){return `${head('EXCEPTION MONITORING','Signal alerts','Review significant disagreement or changes in linked Panta YES prices.',`<button class="btn" data-act="load-alerts">↻ Refresh</button>`)}<div class="section"><div class="section-title"><h2>Alert sensitivity</h2><span class="pill gray">${S.threshold} percentage points</span></div><input type="range" id="alert-threshold" min="5" max="50" step="5" value="${S.threshold}" style="width:100%;accent-color:var(--lime)"><p class="subnote">Signals are evaluated when you open this page. No email notifications or background price updates are configured.</p></div><div class="section" style="margin-top:18px"><div class="section-title"><h2>Attention required</h2><small>${S.alerts.length} signal(s)</small></div>${S.alerts.length?S.alerts.map(a=>`<div class="market-row"><div><h4>${esc(a.title)}</h4><p>${esc(a.market_title)}</p><span class="small-muted">${esc(a.kind==='divergence'?'Team estimate vs market YES price':'Change between last two recorded snapshots')} · ${esc(a.source)}</span></div><div style="text-align:right"><div class="market-price">${a.difference>0?'+':''}${(a.difference*100).toFixed(0)}pp</div><button class="btn btn-mini" data-act="open-decision" data-id="${a.decision_id}">Inspect →</button></div></div>`).join(''):blank('No significant deviations','Link markets to decisions and record quotes to calculate deviations.')}</div>${footer()}`}
function labView(){const ds=S.overview?.decisions.filter(d=>d.status==='open')||[];const selected=ds.find(d=>d.id===S.labDecisionId)||ds[0];const p=selected?.team_probability;const impact=selected?.impact_usd||0;const risk=p==null?null:impact*(1-p);return `${head('SCENARIO STUDIO','What if we’re wrong?','Explore downside and opportunity scenarios using your team’s recorded estimates.')}${ds.length?`<div class="risk-layout"><div class="section"><div class="section-title"><h2>Choose a decision</h2></div><select class="select" id="lab-decision">${ds.map(d=>`<option value="${d.id}" ${selected?.id===d.id?'selected':''}>${esc(d.title)}</option>`).join('')}</select><div class="subsection"><span class="labeled-value">QUESTION</span><h3 style="line-height:1.45">${esc(selected?.question)}</h3></div><div class="risk-gauge"><div class="risk-circle" style="background:conic-gradient(var(--mint) ${p==null?0:p*100}%,#2f4150 0)"><strong>${pct(p)}</strong><small>Team YES estimate</small></div></div><p class="subnote">This chart uses the latest forecast from each member. It is not generated by Panta and it is not a trained AI prediction.</p></div><div class="section"><div class="section-title"><h2>Risk exposure estimate</h2></div><div class="eyebrow">ASSUMED BUSINESS IMPACT</div><h3 style="font-size:33px;margin:6px 0 19px">${usd(impact)}</h3><div class="exposure"><span class="subnote">Expected downside if this outcome fails</span><strong>${risk==null?'—':usd(risk)}</strong><span class="subnote">Example formula: downside amount × (1 − team YES estimate). Not a return forecast.</span></div><div class="subsection"><div class="entry"><strong>Optimistic outcome</strong><p>The measurable YES event occurs. Exposure under this single-event scenario: $0.</p></div><div class="entry"><strong>Failure outcome</strong><p>If the YES event does not occur, assumed downside: ${usd(impact)}.</p></div><div class="entry"><strong>Unknowns</strong><p>Uncertainty, dependencies, and multi-event effects are not modeled. Add evidence to improve the decision process.</p></div></div><button class="btn btn-primary" data-act="open-decision" data-id="${selected.id}">Review decision →</button></div></div>`:blank('Create a decision first','Scenario lab needs an active decision with a team estimate.')}${footer()}`}
function teamView(){const m=S.overview?.members||[],role=m.find(x=>x.id===S.user?.id)?.role;return `${head('COLLABORATION','Team & activity','Invite collaborators, audit changes, and export evidence-backed decisions.',`<button class="btn" data-act="new-workspace">+ Workspace</button>`)}<div class="cols"><div><div class="section"><div class="section-title"><h2>Workspace members</h2><span class="pill gray">${m.length} members</span></div>${m.map(x=>`<div class="member"><div class="user-initials">${esc(x.display_name.slice(0,1).toUpperCase())}</div><div style="flex:1"><strong>${esc(x.display_name)}</strong><small>${esc(x.email)}</small></div>${pill(x.role)}</div>`).join('')}${role==='owner'?`<button class="btn btn-mini" data-act="invite" style="margin-top:15px">+ Invite teammate</button>`:''}</div><div class="section" style="margin-top:17px"><div class="section-title"><h2>Data portability</h2></div><p class="subnote">Your workspace records are stored in the configured database (PostgreSQL in the cloud, SQLite locally). Export decisions, forecasts, evidence, and linked markets anytime.</p><div class="toolbar"><a class="btn btn-mini" href="/api/workspaces/${S.ws}/export" download>↓ JSON export</a><a class="btn btn-mini" href="/api/workspaces/${S.ws}/csv" download>↓ CSV export</a></div></div></div><div class="section"><div class="section-title"><h2>Activity log</h2><button class="btn btn-mini" data-act="load-activity">↻</button></div><div class="activity">${S.activity.length?S.activity.map(x=>`<div class="activity-row"><span class="activity-dot"></span><div><b>${esc(x.event.replaceAll('_',' '))}</b><span style="color:#c2d2df">${esc(x.detail)}</span><small>${esc(x.author)} · ${esc(dateTime(x.created_at))}</small></div></div>`).join(''):blank('Nothing to show yet','Changes will be recorded in the audit trail.')}</div></div></div>${footer()}`}
function render(){const root=$('#app');if(!S.user){root.innerHTML=authPage();return}root.innerHTML=chrome();const views={dashboard:overviewView,decisions:decisionsView,markets:marketsView,alerts:alertsView,lab:labView,team:teamView,detail:detailView};$('#content').innerHTML=(views[S.view]||overviewView)();}
function modal(title,body,buttons=''){const node=$('#modal-root');node.innerHTML=`<div class="overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" data-act="close-modal" aria-label="Close">×</button></div>${body}${buttons}</div></div>`;node.querySelector('input,textarea,select,button')?.focus()}
function closeModal(){$('#modal-root').innerHTML=''}
const foot=(label)=>`<div class="modal-foot"><button class="btn" type="button" data-act="close-modal">Cancel</button><button class="btn btn-primary" type="submit">${esc(label)}</button></div>`;
const labelInput=(label,name,placeholder='',type='text',required=true,value='')=>`<div class="field"><label class="form-label" for="form-${name}">${esc(label)}</label><input class="input" id="form-${name}" name="${name}" type="${type}" ${required?'required':''} ${type==='number'?'min="0" max="1000000000000"':''} placeholder="${esc(placeholder)}" value="${esc(value)}"></div>`;
const area=(label,name,placeholder='',required=false,value='')=>`<div class="field"><label class="form-label" for="form-${name}">${esc(label)}</label><textarea class="textarea" id="form-${name}" name="${name}" ${required?'required':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea></div>`;
function decisionModal(edit=false){const d=edit?S.detail:null;modal(edit?'Edit decision room':'New decision room',`<form id="decision-form">${labelInput('Short title','title','e.g. Enterprise expansion', 'text',true,d?.title)}${area('Measurable YES / NO question','question','Will we sign 3 enterprise contracts by December 31?',true,d?.question)}${area('Resolution criteria / context','description','Define the event, deadline, and evidence needed to settle the outcome.',false,d?.description)}<div class="form-grid">${labelInput('Category','category','Strategy','text',false,d?.category||'Strategy')}${labelInput('Resolution deadline','deadline','','date',false,d?.deadline||'')}</div>${labelInput('Assumed downside if NO (USD)','impact_usd','0','number',false,d?.impact_usd||0)}${foot(edit?'Save changes':'Create decision room')}</form>`)}
function forecastModal(){modal('Record your forecast',`<form id="forecast-form"><p class="subnote">${esc(S.detail.question)}</p><div class="field" style="margin-top:20px"><label class="form-label" for="forecast-n">Your YES estimate: <span id="forecast-value">50%</span></label><input style="width:100%;accent-color:var(--lime)" type="range" name="probability" id="forecast-n" min="0" max="100" value="${S.detail.team_probability==null?50:Math.round(S.detail.team_probability*100)}"></div>${area('Reasoning (optional)','reason','Why do you believe this probability?')}${foot('Save forecast')}</form>`)}
function evidenceModal(){modal('Add evidence',`<form id="note-form">${area('Evidence note','body','Summarize a source or describe what changed.',true)}${labelInput('Reference link (optional)','source_url','https://example.com/report','url',false)}${foot('Add evidence')}</form>`)}
function resolveModal(){modal('Resolve this outcome',`<form id="resolve-form"><div class="callout">This locks new forecasts and marks the objective outcome. Only workspace owners can resolve a decision.</div><h3>${esc(S.detail.question)}</h3><div class="field"><label class="form-label">Verified real-world outcome</label><select class="select" name="outcome"><option value="yes">YES — it occurred</option><option value="no">NO — it did not occur</option></select></div>${foot('Confirm resolution')}</form>`)}
function linkModal(preselected=null){const markets=S.marketData?.items||[];const options=markets.map(m=>`<option value="${esc(m.marketId)}">${esc(m.title.slice(0,100))} (${esc(m.source||S.marketSource)})</option>`).join('');let html=`<form id="link-form"><div class="callout info">Link only markets with matching resolution criteria. A demo market is never presented as a real Panta market.</div><div class="field"><label class="form-label">Market ID</label><input class="input" name="market_id" required value="${esc(preselected?.marketId||'')}" placeholder="Paste a real Panta market ID or choose from catalog"></div><div class="field"><label class="form-label">Source</label><select class="select" name="source"><option value="live" ${preselected?.source==='live'?'selected':''}>Live Panta market</option><option value="demo" ${preselected?.source==='demo'||!preselected?'selected':''}>Synthetic demo example</option></select></div>${markets.length?`<p class="prompt">Catalog suggestion:</p><select id="link-suggestion" class="select"><option value="">Choose an example…</option>${options}</select>`:''}${area('Why does this market match your decision?','match_explanation','Explain matching outcome, time horizon, and resolution rules.',true)}${foot('Attach market')}</form>`;modal('Attach Panta signal',html)}
async function navigate(view){try{S.view=view;if(view==='markets'){S.pantaStatus=await api('/api/panta/status');if(!S.marketData){S.marketSource='demo';S.marketData=await api('/api/markets/demo')}}if(view==='alerts'){const x=await api(`/api/workspaces/${S.ws}/alerts?threshold=${S.threshold/100}`);S.alerts=x.alerts}if(view==='team'){const x=await api('/api/workspaces/'+S.ws+'/activity');S.activity=x.activity}render();window.scrollTo(0,0)}catch(e){toast(e.message,true)}}
async function openDecision(id){S.detail=await api('/api/decisions/'+id);await navigate('detail')}
async function reload(){await loadOverview();if(S.view==='detail'&&S.detail)S.detail=await api('/api/decisions/'+S.detail.id);render()}
async function doAction(node){const act=node.dataset.act;const id=node.dataset.id;try{
 if(act==='auth-switch'){S.authMode=S.authMode==='login'?'register':'login';render()}
 else if(act==='auth-retry'){try{const session=await refreshAuth();if(!session.user)showAuthError('No active session. Please sign in.');}catch(e){if($('#auth-error'))showAuthError(e.message);else showConnectivityError(e.message)}}
 else if(act==='logout'){await api('/api/auth/logout','POST',{});S.user=null;S.csrf='';S.ws=null;render()}
 else if(act==='new-decision')decisionModal(false);
 else if(act==='edit-decision')decisionModal(true);
 else if(act==='close-modal')closeModal();
 else if(act==='new-forecast')forecastModal();
 else if(act==='add-note')evidenceModal();
 else if(act==='resolve')resolveModal();
 else if(act==='open-decision')await openDecision(+id);
 else if(act==='share-report'){const status=await api('/api/decisions/'+S.detail.id+'/report');modal('Public decision report',`<p class="subnote">A public read-only share contains the decision title, question, description, aggregate team forecast, resolution, and linked market price history. No emails, team names, private evidence notes or individual forecasts are included.</p><div class="callout info">Share access expires after 7 days. Anyone with the link can read it. Creating a new link revokes any previous share link for this decision.</div>${status.active?`<p>There is an active report (expires ${esc(dateTime(new Date(status.expires_at*1000).toISOString()))}).</p><button class="btn" data-act="revoke-report">Revoke existing link</button>`:''}<button class="btn btn-primary" data-act="create-report">${status.active?'Replace share link':'Create share link'}</button>`)}
 else if(act==='create-report'){if(!confirm('Publish this decision summary and linked market history to anyone with the private link for 7 days?'))return;const result=await api('/api/decisions/'+S.detail.id+'/report','POST',{});const link=location.origin+'/share?t='+encodeURIComponent(result.token);modal('Shareable Decision Report',`<p class="subnote">Copy this once. The full secret link is not stored by the server.</p><div class="field"><input class="input" id="report-url" readonly aria-label="Decision report URL" value="${esc(link)}"></div><button class="btn btn-primary" data-act="copy-report">Copy report URL</button><p class="subnote">Expires in 7 days. You can revoke or replace this link at any time.</p>`)}
 else if(act==='copy-report'){await navigator.clipboard.writeText($('#report-url').value);toast('Decision report link copied')}
 else if(act==='revoke-report'){if(!confirm('Revoke the current public link?'))return;await api('/api/decisions/'+S.detail.id+'/report','DELETE');closeModal();toast('Public report link revoked')}
 else if(act==='panta-check'){S.pantaVerified=await api('/api/panta/check','POST',{});render();toast('Panta market listing verified') }
 else if(act==='market-mode'){S.marketSource=node.dataset.source;S.marketData=S.marketSource==='demo'?await api('/api/markets/demo'):null;S.marketCursor='';S.marketCategory='';if(S.marketSource==='live'&&S.panta){try{S.marketCategories=(await api('/api/markets/categories')).categories}catch(e){toast('Could not load market categories: '+e.message,true)}}render()}
 else if(act==='fetch-markets'){S.marketCategory=$('#market-category').value;S.marketPhase=$('#market-phase').value;S.marketData=await api(`/api/markets?category=${encodeURIComponent(S.marketCategory)}&phase=${encodeURIComponent(S.marketPhase)}`);render();toast('Live catalog loaded from Panta')}
 else if(act==='more-markets'){const p=await api(`/api/markets?category=${encodeURIComponent(S.marketCategory||'')}&phase=${encodeURIComponent(S.marketPhase||'')}&cursor=${encodeURIComponent(S.marketData.nextCursor)}`);S.marketData={items:[...S.marketData.items,...p.items],nextCursor:p.nextCursor};render()}
 else if(act==='market-detail'){let m=S.marketData.items.find(m=>m.marketId===id);if(S.marketSource==='live')m=await api('/api/markets/'+encodeURIComponent(id));modal('Market details',`<h3>${esc(m.title)}</h3><div class="meta">${pill(m.source)}${pill(m.phase)}</div><p class="subnote">${esc(m.description)}</p><div class="cards-2" style="margin:20px 0"><div class="stat"><small>YES quote</small><strong>${pct(m.yesPrice)}</strong></div><div class="stat"><small>NO quote</small><strong>${pct(m.noPrice)}</strong></div></div>${m.yesPrice==null&&m.noPrice==null?'<div class="callout info" role="status">Panta returned no YES/NO prices for this market detail. A dash means unavailable, not 0% and not an API authentication failure.</div>':''}${m.quoteOrigin==='market_catalog'?'<p class="subnote">Quote source: freshly fetched Panta market catalog (the market detail omitted its YES price).</p>':''}${m.titleAvailable===false?'<p class="subnote">Panta did not provide a market title. The displayed identifier is a fallback, not an official title.</p>':''}<p class="subnote">Market ID: ${esc(m.marketId)}</p><div class="callout info">Prices are not guaranteed to be calibrated event probabilities. Please review market resolution rules before making decisions.</div><button class="btn" data-act="close-modal">Close</button>`)}
 else if(act==='link-selected'){const m=S.marketData.items.find(m=>m.marketId===id);if(!m)return;S.linkMarketCandidate=m;await loadOverview();const decisions=S.overview.decisions.filter(d=>d.status==='open');if(!decisions.length){toast('No open decisions are listed for this workspace. Check Decision rooms, then retry.',true);return}modal('Choose decision room',`<form id="choose-link-form"><div class="field"><label class="form-label">Attach ${esc(m.title)} to:</label><select name="decision_id" class="select">${decisions.map(d=>`<option value="${d.id}">${esc(d.title)}</option>`).join('')}</select></div>${foot('Continue')}</form>`)}
 else if(act==='link-market'){S.linkMarketCandidate=null;linkModal()}
 else if(act==='refresh-link'){const outcome=await api('/api/links/'+id+'/refresh','POST',{});await reload();const reason=outcome.market?.quoteDiagnostics?.reason;const why=reason==='catalog_page_missing_market'?'Panta detail has no YES quote and this market was not in the checked catalog page':reason==='matched_market_unpriced'?'Panta returned this market without a YES quote':'Panta returned no valid YES quote';toast(outcome.snapshot_result==='updated'?'New Panta quote snapshot recorded':outcome.snapshot_result==='unchanged'?'Quote unchanged — no duplicate snapshot':why+'; snapshot skipped',outcome.snapshot_result==='unpriced')}
 else if(act==='remove-link'){if(!confirm('Unlink this market and its stored snapshots?'))return;await api('/api/links/'+id,'DELETE');await reload();toast('Market unlinked')}
 else if(act==='load-alerts'){const a=await api(`/api/workspaces/${S.ws}/alerts?threshold=${S.threshold/100}`);S.alerts=a.alerts;render();toast('Alerts recalculated')}
 else if(act==='load-activity'){S.activity=(await api('/api/workspaces/'+S.ws+'/activity')).activity;render()}
 else if(act==='change-workspace'){modal('Switch workspace',`<form id="workspace-select"><div class="field"><select class="select" name="ws">${S.workspaces.map(w=>`<option value="${w.id}" ${S.ws===w.id?'selected':''}>${esc(w.name)} (${esc(w.role)})</option>`).join('')}</select></div>${foot('Switch workspace')}</form><button class="btn btn-mini" data-act="new-workspace">Create a new workspace</button>`)}
 else if(act==='new-workspace'){modal('New workspace',`<form id="workspace-form">${labelInput('Workspace name','name','Acme strategic decisions')}${foot('Create workspace')}</form>`)}
 else if(act==='invite'){const x=await api(`/api/workspaces/${S.ws}/invites`,'POST',{});const url=location.origin+'/app?invite='+encodeURIComponent(x.token);modal('Invite teammate',`<p class="subnote">Share this link privately. It expires in 24 hours. The recipient must create an OutcomeOS account or sign in.</p><div class="field"><input class="input" aria-label="Invite link" readonly value="${esc(url)}" id="invite-url"></div><button class="btn btn-primary" data-act="copy-invite">Copy invite link</button>`)}
 else if(act==='copy-invite'){await navigator.clipboard.writeText($('#invite-url').value);toast('Invite link copied')}
 else if(act==='accept-invite'){const token=new URLSearchParams(location.search).get('invite');if(!token)return;const r=await api('/api/invites/accept','POST',{token});history.replaceState({},'',location.pathname);S.ws=r.workspace_id;S.workspaces=(await api('/api/workspaces')).workspaces;await loadOverview();S.view='dashboard';render();toast('Joined the workspace')}
 }catch(e){toast(e.message,true)}}
async function submitForm(form){const f=Object.fromEntries(new FormData(form));try{
 if(form.id==='auth-form'){
  const button=form.querySelector('[type="submit"]');
  const previousLabel=button?.textContent;
  const field=$('#auth-error');if(field){field.hidden=true;field.textContent='';}
  if(button){button.disabled=true;button.textContent='Connecting…';}
  try{
   const data=await api('/api/auth/'+(S.authMode==='register'?'register':'login'),'POST',f);
   S.csrf=data.csrf||'';
   const session=await refreshAuth();
   if(!session.user){
    throw new Error('Sign-in was accepted, but the session cookie was not retained. Try the Production URL in a regular browser.');
   }
   const inviteToken=new URLSearchParams(location.search).get('invite');
   if(inviteToken){modal('Join shared workspace',`<p class="subnote">You have been invited to collaborate on a decision workspace.</p><button class="btn btn-primary" data-act="accept-invite">Accept invitation →</button>`);}
   toast('Welcome to OutcomeOS');
  }catch(error){showAuthError(error.message||'Unable to sign in. Please retry.');}
  finally{if(button?.isConnected){button.disabled=false;button.textContent=previousLabel;}}
  return;
 }
 if(form.id==='decision-form'){
  const editing=S.view==='detail';
  const created=editing?await api('/api/decisions/'+S.detail.id,'PATCH',f):await api('/api/workspaces/'+S.ws+'/decisions','POST',f);
  closeModal();
  let listed=false,refreshError=null;
  for(let attempt=0;attempt<3;attempt++){
   try{
    await reload();
    listed=editing || !!S.overview?.decisions?.some(d=>Number(d.id)===Number(created.id) && d.status==='open');
    if(listed)break;
   }catch(e){refreshError=e;}
   if(attempt<2)await pause(450*(attempt+1));
  }
  if(!listed){
   toast('Decision creation was accepted, but the updated list could not be confirmed. Do not create a duplicate. Reload Decision rooms; '+(refreshError?.message||'check the workspace and Vercel logs.'),true);
   return;
  }
  toast('Decision saved and verified in this workspace');
 }
 else if(form.id==='forecast-form'){await api('/api/decisions/'+S.detail.id+'/forecasts','POST',f);closeModal();await reload();toast('Forecast recorded')}
 else if(form.id==='note-form'){await api('/api/decisions/'+S.detail.id+'/notes','POST',f);closeModal();await reload();toast('Evidence saved')}
 else if(form.id==='resolve-form'){await api('/api/decisions/'+S.detail.id+'/resolve','POST',{outcome:f.outcome==='yes'});closeModal();await reload();toast('Decision resolved and calibration updated')}
 else if(form.id==='link-form'){await api('/api/decisions/'+S.detail.id+'/links','POST',f);closeModal();await reload();toast('Market linked to decision')}
 else if(form.id==='choose-link-form'){S.detail=await api('/api/decisions/'+f.decision_id);S.view='detail';linkModal(S.linkMarketCandidate)}
 else if(form.id==='workspace-form'){const r=await api('/api/workspaces','POST',f);S.ws=r.id;S.workspaces=(await api('/api/workspaces')).workspaces;await loadOverview();closeModal();S.view='dashboard';render();toast('Workspace created')}
 else if(form.id==='workspace-select'){S.ws=+f.ws;await loadOverview();closeModal();S.view='dashboard';render()}
 }catch(e){toast(e.message,true)}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-act]');const n=e.target.closest('[data-view]');if(a){e.preventDefault();doAction(a)}else if(n){e.preventDefault();navigate(n.dataset.view)}else if(e.target.classList?.contains('overlay'))closeModal()});
document.addEventListener('submit',e=>{if(e.target.matches('form')){e.preventDefault();submitForm(e.target)}});
document.addEventListener('input',e=>{if(e.target.id==='forecast-n'){$('#forecast-value').textContent=e.target.value+'%'}if(e.target.id==='market-query'){S.marketSearch=e.target.value;const pos=e.target.selectionStart;$('#content').innerHTML=marketsView();const dest=$('#market-query');dest.focus();dest.setSelectionRange(pos,pos)}if(e.target.id==='decision-search'){S.search=e.target.value;const pos=e.target.selectionStart;const el=e.target;$('#content').innerHTML=decisionsView();let dest=$('#decision-search');dest.focus();dest.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.id==='lab-decision'){S.labDecisionId=+e.target.value;render()}if(e.target.id==='alert-threshold'){S.threshold=+e.target.value;navigate('alerts')}if(e.target.id==='link-suggestion'){const market=S.marketData.items.find(m=>m.marketId===e.target.value);if(market){$('#link-form [name="market_id"]').value=market.marketId;$('#link-form [name="source"]').value=market.source||S.marketSource}}});
refreshAuth().then(()=>{const invite=new URLSearchParams(location.search).get('invite');if(invite&&S.user){modal('Join shared workspace',`<p class="subnote">You have been invited to collaborate on a decision workspace.</p><button class="btn btn-primary" data-act="accept-invite">Accept invitation →</button>`)}}).catch(e=>{
 console.error('[OutcomeOS] Initial session check failed:',e?.message||'unknown error');
 // A temporary network error must not silently appear as a logged-out session.
 showConnectivityError((e?.message||'Unable to connect to the server')+' Please retry when the server is available.');
});
